CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_bloquear_usuario` (IN `p_usuario` VARCHAR(50), IN `p_bloqueado` TINYINT(1))   BEGIN
            UPDATE usuarios 
            SET bloqueado = p_bloqueado 
            WHERE usuario = p_usuario;
        END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_cambiar_estado_socio` (IN `p_numero_accion` INT, IN `p_nuevo_estado` VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, IN `p_motivo` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci)   BEGIN
        DECLARE v_existe_accion INT DEFAULT 0;

        SELECT COUNT(*) INTO v_existe_accion FROM acciones WHERE numero_accion = p_numero_accion;

        IF v_existe_accion = 0 THEN
            SIGNAL SQLSTATE '45000' 
            SET MESSAGE_TEXT = 'Error: El número de acción no existe.';
        ELSE
            IF p_nuevo_estado IN ('ACTIVO', 'INACTIVO', 'SUSPENDIDO', 'TRANSFERIDO', 'CANCELADO') THEN
                IF p_nuevo_estado = 'ACTIVO' THEN
                    UPDATE acciones 
                    SET estado = p_nuevo_estado, 
                        fecha_activacion = CURRENT_DATE,
                        motivo_inactivacion = NULL,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE numero_accion = p_numero_accion;
                ELSE
                    UPDATE acciones 
                    SET estado = p_nuevo_estado, 
                        fecha_inactivacion = CURRENT_DATE,
                        motivo_inactivacion = p_motivo,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE numero_accion = p_numero_accion;
                END IF;

                SELECT 
                    a.numero_accion,
                    CONCAT_WS(' ', p.primer_nombre, p.primer_apellido) AS socio,
                    a.estado,
                    a.fecha_activacion,
                    a.fecha_inactivacion,
                    a.motivo_inactivacion,
                    a.updated_at
                FROM acciones a
                JOIN personas p ON a.persona_id = p.id
                WHERE a.numero_accion = p_numero_accion;
            ELSE
                SIGNAL SQLSTATE '45000' 
                SET MESSAGE_TEXT = 'Error: Estado no válido. Use ACTIVO, INACTIVO, SUSPENDIDO, TRANSFERIDO o CANCELADO.';
            END IF;
        END IF;
    END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_crear_postulado` (IN `p_tipomiembro` VARCHAR(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, IN `p_cedula` VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, IN `p_nacionalidad_id` INT, IN `p_primer_nombre` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, IN `p_segundo_nombre` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, IN `p_primer_apellido` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, IN `p_segundo_apellido` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, IN `p_correo_electronico` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, IN `p_profesion` VARCHAR(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, IN `p_tipo_referencia` ENUM('SOCIO','EMPRESA'), IN `p_referencia_id` INT, IN `p_foto` MEDIUMBLOB)   BEGIN
        DECLARE v_existe_postulado INT DEFAULT 0;
        DECLARE v_existe_referencia INT DEFAULT 0;
        DECLARE v_nombre_completo VARCHAR(400);
        DECLARE v_referencia_nombre VARCHAR(200);
        
        IF p_cedula IS NULL OR TRIM(p_cedula) = '' THEN
            SIGNAL SQLSTATE '45000' 
            SET MESSAGE_TEXT = 'Error: La cédula es obligatoria.';
        END IF;
        
        IF p_primer_nombre IS NULL OR TRIM(p_primer_nombre) = '' THEN
            SIGNAL SQLSTATE '45000' 
            SET MESSAGE_TEXT = 'Error: El primer nombre es obligatorio.';
        END IF;
        
        IF p_primer_apellido IS NULL OR TRIM(p_primer_apellido) = '' THEN
            SIGNAL SQLSTATE '45000' 
            SET MESSAGE_TEXT = 'Error: El primer apellido es obligatorio.';
        END IF;
        
        IF p_tipomiembro NOT IN ('PRINCIPAL', 'SUPLENTE', 'VOCAL 1', 'VOCAL 2', 'VOCAL 3', 
                                 'PRESIDENTE', 'VICEPRESIDENTE', 'SECRETARIO', 'TESORERO') THEN
            SIGNAL SQLSTATE '45000' 
            SET MESSAGE_TEXT = 'Error: Tipo de miembro no válido.';
        END IF;
        
        SELECT COUNT(*) INTO v_existe_postulado 
        FROM postulados 
        WHERE cedula = p_cedula;
        
        IF v_existe_postulado > 0 THEN
            SIGNAL SQLSTATE '45000' 
            SET MESSAGE_TEXT = 'Error: Ya existe un postulado con esta cédula.';
        END IF;
        
        IF p_tipo_referencia IS NOT NULL AND p_referencia_id IS NOT NULL THEN
            IF p_tipo_referencia = 'SOCIO' THEN
                SELECT COUNT(*) INTO v_existe_referencia
                FROM acciones a
                JOIN personas p ON a.persona_id = p.id
                WHERE p.id = p_referencia_id AND a.estado = 'ACTIVO';
                
                IF v_existe_referencia = 0 THEN
                    SIGNAL SQLSTATE '45000' 
                    SET MESSAGE_TEXT = 'Error: El socio de referencia no existe o no está activo.';
                END IF;
                
            ELSEIF p_tipo_referencia = 'EMPRESA' THEN
                SELECT COUNT(*) INTO v_existe_referencia
                FROM empresas
                WHERE id_empresa = p_referencia_id;
                
                IF v_existe_referencia = 0 THEN
                    SIGNAL SQLSTATE '45000' 
                    SET MESSAGE_TEXT = 'Error: La empresa de referencia no existe.';
                END IF;
            END IF;
        END IF;
        
            tipomiembro,
            cedula,
            nacionalidad_id,
            primer_nombre,
            segundo_nombre,
            primer_apellido,
            segundo_apellido,
            correo_electronico,
            profesion,
            tipo_referencia,
            referencia_id,
            foto,
            en_votacion
        ) VALUES (
            UPPER(TRIM(p_tipomiembro)),
            TRIM(p_cedula),
            COALESCE(p_nacionalidad_id, 1),
            TRIM(p_primer_nombre),
            TRIM(COALESCE(p_segundo_nombre, '')),
            TRIM(p_primer_apellido),
            TRIM(COALESCE(p_segundo_apellido, '')),
            TRIM(COALESCE(p_correo_electronico, '')),
            TRIM(COALESCE(p_profesion, '')),
            p_tipo_referencia,
            p_referencia_id,
            p_foto,
            0  
        );
        
        SET v_nombre_completo = CONCAT_WS(' ', 
            TRIM(p_primer_nombre), 
            TRIM(COALESCE(p_segundo_nombre, '')), 
            TRIM(p_primer_apellido), 
            TRIM(COALESCE(p_segundo_apellido, ''))
        );
        
        IF p_tipo_referencia = 'SOCIO' AND p_referencia_id IS NOT NULL THEN
            SELECT CONCAT(CONCAT_WS(' ', p.primer_nombre, p.primer_apellido), ' (Acción: ', a.numero_accion, ')')
            INTO v_referencia_nombre
            FROM personas p
            JOIN acciones a ON p.id = a.persona_id
            WHERE p.id = p_referencia_id
            LIMIT 1;
            
        ELSEIF p_tipo_referencia = 'EMPRESA' AND p_referencia_id IS NOT NULL THEN
            SELECT CONCAT(nombre_empresa, ' (RIF: ', rif_empresa, ')')
            INTO v_referencia_nombre
            FROM empresas
            WHERE id_empresa = p_referencia_id
            LIMIT 1;
        END IF;
        
        SELECT 
            p_cedula AS cedula,
            COALESCE(p_nacionalidad_id, 1) AS nacionalidad_id,
            v_nombre_completo AS nombre_completo,
            TRIM(p_primer_nombre) AS primer_nombre,
            TRIM(COALESCE(p_segundo_nombre, '')) AS segundo_nombre,
            TRIM(p_primer_apellido) AS primer_apellido,
            TRIM(COALESCE(p_segundo_apellido, '')) AS segundo_apellido,
            UPPER(TRIM(p_tipomiembro)) AS tipomiembro,
            TRIM(COALESCE(p_correo_electronico, '')) AS correo_electronico,
            TRIM(COALESCE(p_profesion, '')) AS profesion,
            p_tipo_referencia AS tipo_referencia,
            p_referencia_id AS referencia_id,
            COALESCE(v_referencia_nombre, 'Sin referencia') AS referencia_nombre,
            0 AS en_votacion,
            'Postulado creado exitosamente' AS mensaje;
    END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_crear_usuario` (IN `p_usuario` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, IN `p_cedula` VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, IN `p_contrasena` VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, IN `p_tipousuario` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, IN `p_email` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci, IN `p_puestotrabajo` VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci)   BEGIN
        DECLARE user_exists INT DEFAULT 0;
        DECLARE v_tipo_id INT DEFAULT NULL;
        DECLARE v_puesto_id INT DEFAULT NULL;

        SELECT COUNT(*) INTO user_exists FROM usuarios WHERE usuario = p_usuario;

        IF user_exists > 0 THEN
            SIGNAL SQLSTATE '45000' 
            SET MESSAGE_TEXT = 'Error: El nombre de usuario ya se encuentra registrado.';
        ELSE
            -- Resolver tipo_usuario_id si viene como número o como nombre
            IF p_tipousuario REGEXP '^[0-9]+$' THEN
                SET v_tipo_id = CAST(p_tipousuario AS UNSIGNED);
            ELSE
                SELECT id INTO v_tipo_id FROM tipos_usuario WHERE UPPER(nombre) = UPPER(TRIM(p_tipousuario)) COLLATE utf8mb4_unicode_ci LIMIT 1;
                IF v_tipo_id IS NULL THEN
                    SET v_tipo_id = 2; -- Default Operador o Usuario si no existe
                END IF;
            END IF;

            -- Resolver puesto_trabajo_id si viene como número o como nombre
            IF p_puestotrabajo IS NOT NULL AND TRIM(p_puestotrabajo) != '' THEN
                IF p_puestotrabajo REGEXP '^[0-9]+$' THEN
                    SET v_puesto_id = CAST(p_puestotrabajo AS UNSIGNED);
                ELSE
                    SELECT id INTO v_puesto_id FROM puestos_trabajo WHERE UPPER(nombre) = UPPER(TRIM(p_puestotrabajo)) COLLATE utf8mb4_unicode_ci LIMIT 1;
                END IF;
            END IF;

            -- Insertar con el esquema actual de la tabla usuarios
                usuario, 
                contrasena, 
                tipo_usuario_id, 
                email, 
                puesto_trabajo_id, 
                bloqueado
            ) VALUES (
                TRIM(p_usuario), 
                p_contrasena, 
                v_tipo_id, 
                TRIM(p_email), 
                v_puesto_id, 
                0
            );
            
            SELECT 'Usuario creado exitosamente' AS resultado;
        END IF;
    END$$

DELIMITER ;

