CREATE TRIGGER `tr_acciones_insert` AFTER INSERT ON `acciones` FOR EACH ROW BEGIN
    VALUES ('acciones', 'INSERT', NEW.id, 
            JSON_OBJECT(
                'numero_accion', NEW.numero_accion,
                'persona_id', NEW.persona_id,
                'estado', NEW.estado
            ),
             @current_user_id, CURRENT_USER()) ;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `tr_acciones_update` AFTER UPDATE ON `acciones` FOR EACH ROW BEGIN
    VALUES ('acciones', 'UPDATE', OLD.id, 
            JSON_OBJECT('numero_accion', OLD.numero_accion, 'persona_id', OLD.persona_id, 'estado', OLD.estado),
            JSON_OBJECT('numero_accion', NEW.numero_accion, 'persona_id', NEW.persona_id, 'estado', NEW.estado),
             @current_user_id, CURRENT_USER()) ;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_acciones_after_update` AFTER UPDATE ON `acciones` FOR EACH ROW BEGIN
  
  IF OLD.estado != NEW.estado THEN
       CONCAT('Cambio de estado de ', OLD.estado, ' a ', NEW.estado),
       NEW.updated_by);
  END IF;
  
  
  IF OLD.persona_id != NEW.persona_id THEN
       CONCAT('Cambio de titular de persona_id ', OLD.persona_id, ' a ', NEW.persona_id),
       NEW.updated_by);
  END IF;
END
$$
DELIMITER ;

